import math
# Check required fields
required = ['n', 'm', 'weights_str', 'a_list_str', 'p_list', 'p_total', 'a_list']
for k in required:
    if k not in assign:
        # Missing data
        return (False, None)
n = assign['n']
m = assign['m']
p_list = assign['p_list']
p_total = assign['p_total']
a_list = assign['a_list']
# Basic validations
if not (isinstance(n, int) and n % 2 == 1 and n >= 101):
    # n must be odd and reasonably large
    return (False, None)
if not (isinstance(m, int) and m >= 3):
    return (False, None)
if not (isinstance(p_list, list) and isinstance(a_list, list)):
    return (False, None)
if len(p_list) != m or len(a_list) != m:
    return (False, None)
if any((not isinstance(x, int) or x <= 0) for x in p_list):
    return (False, None)
if any((not isinstance(a, int)) for a in a_list):
    return (False, None)
if len(set(a_list)) != m:
    # Distinct shifts required for difficulty
    return (False, None)
if sum(p_list) != p_total or p_total <= 0:
    return (False, None)
# Ensure weights sum to 1 exactly
# weights are p_i / p_total, so sum = 1
# Compute S1 = sum w_j a_j, S2 = sum w_j a_j^2 via integer arithmetic
D = sum(p_list[i] * a_list[i] for i in range(m))  # denominator of S2/S1
if D == 0:
    # Would make the ratio undefined
    return (False, None)
N = sum(p_list[i] * (a_list[i] ** 2) for i in range(m))
# Difficulty enforcement: non-uniform weights
if len(set(p_list)) == 1:
    return (False, None)
# Additional difficulty: answer should be sufficiently large
if ((n - 1) // 2) * N <= 100 * D:
    return (False, None)
# Sum of roots: For n odd and sum w_j = 1, the x^n term cancels and degree is n-1.
# Coeff of x^{n-1}: n * sum w_j a_j = n * D / p_total.
# Coeff of x^{n-2}: -C(n,2) * sum w_j a_j^2 = -C(n,2) * N / p_total.
# Sum of roots = - (coeff of x^{n-2}) / (coeff of x^{n-1}) = (C(n,2) * N / p_total) / (n * D / p_total) = (n-1)/2 * (N/D).
# Return reduced fraction as string to avoid floating issues.
num = ((n - 1) // 2) * N
den = D
g = math.gcd(num, den)
num //= g
den //= g
# Ensure the ratio is not trivially equal to a single a_j (prevents shortcut guessing)
for a in a_list:
    if num == a * den:
        return (False, None)
# Final answer format: reduced fraction; if integer, return as int
if den == 1:
    answer = num
else:
    answer = f"{num}/{den}"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

